    MaintenanceContext units;units.profile=vp;ensure_vp_unit_supply_profile(units).world_city_supply_modifier=0;units.team_eras[9]=0;units.players[5]={};auto &u=ensure_vp_unit_supply_profile(units).players[5];u.military=10;u.free=1;u.base_cache=5;u.war_cache=3;
