    set("MAX_UNIT_SUPPLY_PRODMOD",INT64_MAX);set("PRODUCTION_PENALTY_PER_UNIT_OVER_SUPPLY",INT64_MAX);u.military=INT64_MAX;
    check(vp_unit_production_maintenance(supply,5).modifier==-INT64_MAX,"Full int64 cap remains representable with saturating intermediate arithmetic");
